INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b533b8f2-c7b4-43b0-bb9d-d49f62c31fe1','9','geografie-fizica','published',1,161,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b533b8f2-c7b4-43b0-bb9d-d49f62c31fe1','ro','Iarna, un lac îngheață la suprafață, dar peștii supraviețuiesc în apa de dedesubt. Ce proprietate a apei explică acest lucru?','["Apa înghețată este mai densă decât apa lichidă și se scufundă.","La 0 °C apa îngheață, devine mai voluminoasă și mai puțin densă decât la +4 °C, așa că gheața plutește și izolează apa de dedesubt.","Sarea dizolvată împiedică apa de la fund să înghețe.","Curenții calzi de pe fundul lacului topesc gheața."]','Pornește de la densitatea apei. Ea este maximă la +4 °C; când îngheață, apa se dilată și devine mai ușoară, așa că gheața rămâne la suprafață ca o pătură care ține apa lichidă (și viața) dedesubt.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('2b375a9d-f83e-4ae1-9c8b-2921e07f7fb4','9','geografie-fizica','published',2,162,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('2b375a9d-f83e-4ae1-9c8b-2921e07f7fb4','ro','De ce, la munte, rocile se sfărâmă mai repede acolo unde apa pătrunde în crăpături și îngheață noaptea?','["Pentru că gheața dizolvă chimic mineralele din rocă.","Pentru că apa caldă se evaporă și lasă săruri care rup roca.","Pentru că, înghețând, apa își mărește volumul și, ca o pană, dezagregă (sfărâmă) roca.","Pentru că vântul mută fragmentele de rocă dintr-un loc în altul."]','Amintește-ți că apa se dilată când îngheață. Repetând zilnic îngheț–dezgheț în crăpături, presiunea gheții desface roca bucată cu bucată — un adevărat agent de modelare a reliefului.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('7ddb4548-adb8-44bb-bb9a-4a1d47771eef','9','geografie-fizica','published',0,163,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('7ddb4548-adb8-44bb-bb9a-4a1d47771eef','ro','Un submarin coboară de la suprafață (28 °C) până la 1.000 m adâncime, în zona caldă. De ce, sub un anumit nivel, temperatura apei rămâne aproape constantă?','["Pentru că sub circa 500 m razele solare nu mai ajung să încălzească apa, așa că temperatura scade la circa 2 °C și rămâne stabilă.","Pentru că apropierea de scoarța fierbinte încălzește apa spre adânc.","Pentru că apa amestecă uniform căldura, deci rămâne 28 °C peste tot.","Pentru că apa îngheață la 1.000 m adâncime."]','Gândește-te de unde vine căldura: de la Soare, doar la suprafață. Sub circa 500 m energia solară nu mai pătrunde, așa că temperatura coboară la circa 2 °C și rămâne aproape neschimbată, indiferent de latitudine.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('6be3a9d1-0acc-4433-9391-7467ea4c9e2f','9','geografie-fizica','published',3,164,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('6be3a9d1-0acc-4433-9391-7467ea4c9e2f','ro','Mareele ating valoarea maximă (flux puternic) de două ori pe lună. În ce situație se întâmplă acest lucru?','["Când Luna se află în cuadratură (unghi drept) față de Soare.","Când apa oceanului atinge cea mai mare salinitate.","Când bat cel mai tare vânturile de vest.","Când Soarele, Luna și Pământul sunt aliniate (conjuncție sau opoziție), la Lună nouă și la Lună plină."]','Mareele sunt provocate de atracția Lunii și a Soarelui. Când cei doi trag în aceeași direcție, aliniați cu Pământul, forțele se adună și fluxul este maxim; când trag în unghi drept, se anulează parțial și mareea este minimă.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('9f01a56e-6740-4491-9f80-e6d5a4d0a2c3','9','geografie-fizica','published',1,165,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('9f01a56e-6740-4491-9f80-e6d5a4d0a2c3','ro','Două orașe se află la aceeași latitudine, pe țărmuri opuse ale unui ocean. Unul are ierni blânde, celălalt ierni aspre. Ce factor oceanic explică cel mai bine diferența?','["Salinitatea diferită a apei din dreptul celor două orașe.","Un curent oceanic cald care încălzește țărmul cu ierni blânde, față de un curent rece la celălalt țărm.","Adâncimea diferită a oceanului lângă cele două orașe.","Culoarea diferită a apei mării."]','Curenții oceanici cară căldură pe distanțe uriașe. Un curent cald (precum cel al Golfului) încălzește aerul și țărmul spre care curge, în timp ce un curent rece răcește țărmul opus, deși latitudinea este aceeași.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('a7314d5d-77c8-469b-9007-e1a5c684292f','9','geografie-fizica','published',2,166,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('a7314d5d-77c8-469b-9007-e1a5c684292f','ro','Pe hartă vezi o apă curgătoare mare, cu numeroși afluenți, care se varsă în mare printr-o deltă. Cum o numim și cum se numește suprafața de pe care își adună apa?','["Pârâu; suprafața se numește cumpăna apelor.","Afluent; suprafața se numește confluența.","Fluviu; suprafața se numește bazin hidrografic.","Izvor; suprafața se numește curs superior."]','Mărimea și vărsarea în mare printr-o deltă arată un fluviu. Toată suprafața de pe care își strânge apa prin afluenți este bazinul hidrografic, mărginit de cumpăna apelor (linia culmilor).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('5c3e0a11-2287-44d3-a836-d39ca2bdd1a0','9','geografie-fizica','published',0,167,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('5c3e0a11-2287-44d3-a836-d39ca2bdd1a0','ro','De ce limita zăpezilor permanente este la circa 5.000 m la Ecuator, dar coboară la 0 m la poli?','["Pentru că la Ecuator este cald până la altitudini mari, deci zăpada se menține doar foarte sus, pe când la poli este frig chiar și la nivelul mării.","Pentru că munții de la Ecuator sunt mult mai înalți decât cei de la poli.","Pentru că la poli plouă și ninge mult mai mult decât la Ecuator.","Pentru că la Ecuator zăpada este mai sărată și nu îngheață."]','Leagă temperatura de altitudine și de latitudine. La Ecuator trebuie să urci foarte sus ca să ajungi la frig permanent; la poli frigul este deja la nivelul mării, așa că limita coboară până la 0 m.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('b1d54de6-915f-4847-9530-3b8b95987365','9','geografie-fizica','published',3,168,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('b1d54de6-915f-4847-9530-3b8b95987365','ro','De ce zona ecuatorială primește mult mai multă căldură de la Soare decât zonele polare?','["Pentru că Ecuatorul este cu mii de kilometri mai aproape de Soare.","Pentru că la Ecuator atmosfera lipsește aproape complet.","Pentru că la poli nopțile sunt mai lungi în orice zi a anului.","Pentru că la Ecuator razele solare cad aproape drept și concentrează energia, iar spre poli cad oblic și o împrăștie pe o suprafață mare."]','Nu distanța până la Soare contează, ci unghiul razelor. Razele verticale de la Ecuator încălzesc puternic o suprafață mică; cele oblice de la poli se întind pe o suprafață mare și încălzesc slab.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('77fc60b2-61a6-4538-b56d-974ac5868890','9','geografie-fizica','published',1,169,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('77fc60b2-61a6-4538-b56d-974ac5868890','ro','Climatul ecuatorial are un singur anotimp (cald-ploios), iar cel subecuatorial are două (unul ploios și unul secetos). Ce vegetație corespunde fiecăruia?','["Pădure musonică la ecuatorial, tundră la subecuatorial.","Pădure ecuatorială deasă la ecuatorial, savană la subecuatorial.","Deșert cald la ecuatorial, pădure de foioase la subecuatorial.","Stepă la amândouă."]','Ploaia bogată tot anul hrănește pădurea ecuatorială mereu verde. Alternanța ploios–secetos nu permite pădurea deasă, ci ierburi înalte cu arbori rari — savana.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0bc7cc66-070f-4b2b-b708-33dfe331c17a','9','geografie-fizica','published',2,170,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0bc7cc66-070f-4b2b-b708-33dfe331c17a','ro','La aceeași latitudine, un climat are ierni blânde, veri răcoroase și ploi tot anul, iar altul ierni geroase, veri călduroase și mai puține ploi. Ce explică deosebirea?','["Primul este polar, al doilea ecuatorial.","Primul primește alizee, al doilea musoni.","Primul este oceanic (aproape de mare, care temperează), al doilea continental (în interiorul uscatului, cu contraste mari).","Primul este la munte, al doilea la câmpie."]','Apa se încălzește și se răcește greu, uscatul repede. Aproape de ocean clima este blândă și umedă (oceanică); departe, în interiorul continentului, contrastele dintre iarnă și vară se accentuează (continentală).');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('60bd7c9f-60fd-46b8-8e15-f7c3ab7162cb','9','geografie-fizica','published',0,171,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('60bd7c9f-60fd-46b8-8e15-f7c3ab7162cb','ro','Marile deșerturi calde (ca Sahara) se află în jurul latitudinilor de 20–30°. De ce sunt atât de secetoase, deși sunt foarte calde?','["Pentru că acolo aerul coboară uscat, iar alizeele bat dinspre uscat, aducând foarte puține precipitații (100–250 mm/an).","Pentru că sunt prea departe de Ecuator ca să primească vreo rază de soare.","Pentru că temperaturile scăzute împiedică formarea ploii.","Pentru că musonii aduc acolo ninsori în loc de ploi."]','Compară cu Ecuatorul, unde aerul urcă și plouă. La tropice aerul coboară, uscat, iar alizeele nu aduc umezeală — de aici seceta și deșerturile calde, în ciuda temperaturilor ridicate.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('27389ba9-f866-45bb-998c-ec87cc2d142f','9','geografie-fizica','published',3,172,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('27389ba9-f866-45bb-998c-ec87cc2d142f','ro','Climatul tropical-musonic poate primi vara ploi enorme (până la 12.000 mm), iar iarna aproape deloc. Ce provoacă acest contrast?','["Curenții oceanici reci, care apar doar vara.","Topirea ghețarilor din apropiere.","Salinitatea ridicată a mărilor vecine.","Musonii — vânturi care își schimbă direcția cu anotimpul: vara bat dinspre ocean (umed), iarna dinspre uscat (uscat)."]','Cuvântul-cheie este musonul. Vara vântul bate dinspre ocean și aduce ploi torențiale; iarna își schimbă sensul și bate dinspre uscatul rece, așa că se instalează seceta.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('8b4683b4-6f66-4322-8501-3b99d83341cb','9','geografie-fizica','published',1,173,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('8b4683b4-6f66-4322-8501-3b99d83341cb','ro','De ce, mergând de la Ecuator spre pol, întâlnim tipurile de climă și de vegetație aranjate în fâșii aproape paralele, la fel în ambele emisfere?','["Pentru că vânturile de vest bat identic peste tot pe glob.","Pentru că factorul principal — cantitatea de căldură primită — scade treptat cu latitudinea, simetric față de Ecuator.","Pentru că oceanele au aceeași salinitate peste tot.","Pentru că relieful este identic în cele două emisfere."]','Latitudinea comandă căldura, iar căldura comandă clima și vegetația. Fiindcă energia solară scade simetric de la Ecuator spre fiecare pol, și fâșiile climatice se repetă simetric în cele două emisfere.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('c0f544c9-7af5-40fc-bfe5-ede8fd9a855f','9','geografie-fizica','published',2,174,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('c0f544c9-7af5-40fc-bfe5-ede8fd9a855f','ro','Într-un profil de sol, un orizont închis la culoare (bogat în humus) stă deasupra unuia deschis la culoare, sărăcit. Cum se numesc cele două și de ce diferă?','["Ambele sunt roca-mamă (orizontul C), doar cu umiditate diferită.","Orizontul deschis este humusul, iar cel închis este roca.","Orizontul închis este A (bioacumulativ, bogat în humus), iar cel deschis este E (eluvial, spălat de apă).","Ambele sunt orizontul B de acumulare."]','Culoarea trădează conținutul. Închis înseamnă mult humus, deci orizontul bioacumulativ A; deschis înseamnă spălat de minerale și materie organică de către apa care coboară, deci orizontul eluvial E.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('0d41e677-1f7b-4a1f-9ed6-77088c8d1be2','9','geografie-fizica','published',0,175,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('0d41e677-1f7b-4a1f-9ed6-77088c8d1be2','ro','Orizontul B al unui sol este bogat în argilă, humus și oxizi de fier. De unde provin, cel mai probabil, aceste materiale?','["Au fost spălate de apă din orizonturile de deasupra și depuse (iluviate) aici, mai jos.","Au urcat din roca-mamă prin evaporarea apei.","Au fost aduse de vânt de la suprafața solului.","S-au format prin topirea gheții din adâncul solului."]','Urmărește drumul apei prin sol: de sus în jos. Ea cară argila și oxizii din orizonturile superioare (eluviere) și îi depune mai jos, în orizontul B — proces numit iluviere.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('de94d85b-91d9-46d6-896e-6d049e90112f','9','geografie-fizica','published',3,176,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('de94d85b-91d9-46d6-896e-6d049e90112f','ro','De ce marile tipuri de sol de pe glob urmează, în general, aceleași fâșii ca zonele climatice și de vegetație?','["Pentru că roca-mamă este identică pe tot globul.","Pentru că omul a arat solurile la fel peste tot.","Pentru că timpul de formare este același pretutindeni.","Pentru că clima este factorul pedogenetic cel mai important și hotărăște ce procese formează solul."]','Dintre toți factorii pedogenetici, clima comandă. Ea decide temperatura, ploaia și, prin ele, procesul de formare a solului — de aceea harta solurilor seamănă cu harta climei și a vegetației.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('56087188-bd6e-4764-8a49-fd140081009f','9','geografie-fizica','published',1,177,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('56087188-bd6e-4764-8a49-fd140081009f','ro','Sub pădurea ecuatorială, solurile sunt adesea roșiatice și sărace în substanțe nutritive. Ce proces le explică?','["Calcifierea, care acumulează carbonat de calciu în sol.","Lateritizarea: căldura și apa multă îndepărtează bazele și silicea și lasă în urmă oxizi de fier și aluminiu, roșiatici.","Podzolirea, tipică pădurilor de conifere din climatul rece.","Înghețul repetat, care sfărâmă roca-mamă."]','Leagă clima caldă și umedă de proces. Apa abundentă spală bazele și silicea și lasă pe loc oxizii de fier și aluminiu (de unde culoarea roșie) — lateritizarea, care dă oxisoluri sărace în nutrienți.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('04dadcd1-c336-4751-9755-5b7cf1063f05','9','geografie-fizica','published',2,178,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('04dadcd1-c336-4751-9755-5b7cf1063f05','ro','Solurile de stepă (molisolurile, cernoziomurile) sunt printre cele mai fertile din lume. Ce proces și ce condiții climatice le formează?','["Lateritizarea, într-un climat cald și umed.","Podzolirea, într-un climat răcoros și ploios.","Calcifierea, într-un climat secetos: evaporația este mare, apa nu spală în adânc, iar humusul și carbonatul de calciu se acumulează.","Gleizarea, în locuri băltite, lipsite de oxigen."]','În stepă plouă puțin, așa că apa nu spală substanțele nutritive în adânc. Ierburile lasă mult humus, care se adună într-un orizont gros și bogat — de aici fertilitatea deosebită a cernoziomului.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('80a4046a-baa1-4fde-875d-d3c27f241e78','9','geografie-fizica','published',0,179,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('80a4046a-baa1-4fde-875d-d3c27f241e78','ro','Sub o pădure de conifere, dintr-un climat umed și răcoros, apare un sol cu un orizont deschis, spălat, deasupra unuia de acumulare. Ce proces l-a format?','["Podzolirea: apa spală argila, humusul și compușii de fier și aluminiu din orizontul superior și îi depune mai jos.","Calcifierea: acumularea carbonatului de calciu într-un climat secetos.","Lateritizarea: acumularea oxizilor roșii de fier într-un climat cald.","Salinizarea: acumularea sărurilor la suprafața solului."]','Climatul umed și răcoros și pădurea de conifere sunt semnătura podzolirii. Apa care coboară spală orizontul superior (care rămâne deschis) și depune materialul mai jos, formând spodosoluri.');
INSERT INTO questions (id, grade_id, topic_slug, status, correct_index, position, created_at, updated_at) VALUES ('10a8dfb6-bf1b-480d-92f8-43ca02b42e30','9','geografie-fizica','published',1,180,1783600000000,1783600000000);
INSERT INTO question_translations (question_id, locale, stem, options_json, explanation) VALUES ('10a8dfb6-bf1b-480d-92f8-43ca02b42e30','ro','Un sol nisipos lasă apa să treacă repede, iar unul argilos o reține. Ce proprietate a solului explică deosebirea?','["Culoarea solului.","Textura — dată de mărimea particulelor: nisipul (grăunțe mari) lasă pori largi prin care apa trece ușor, iar argila (particule foarte fine) astupă porii și reține apa.","pH-ul (reacția chimică) a solului.","Cantitatea de humus din sol."]','Gândește-te la mărimea particulelor și la spațiile dintre ele. Boabele mari de nisip lasă pori largi (apa curge), particulele fine de argilă lasă pori minusculi (apa este reținută) — aceasta este textura solului.');
